{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "module TopModule (
    input  logic [5:0] y,
    input  logic       w,
    output logic       Y1,
    output logic       Y3
);

    // One-hot encoding:
    // y[0]=A, y[1]=B, y[2]=C, y[3]=D, y[4]=E, y[5]=F

    // Y1 is next-state for y[1] (state B): only A --1--> B
    assign Y1 = y[0] & w;

    // Y3 is next-state for y[3] (state D): B/C/E/F --0--> D
    assign Y3 = (~w) & (y[1] | y[2] | y[4] | y[5]);

endmodule
",
    "new_content": "`default_nettype none
module TopModule (
    input  logic [5:0] y,
    input  logic       w,
    output logic       Y1,
    output logic       Y3
);

    // One-hot encoding (y[5:0]=000001(A),000010(B),000100(C),001000(D),010000(E),100000(F))
    // y[0]=A, y[1]=B, y[2]=C, y[3]=D, y[4]=E, y[5]=F

    // Y1 is next-state for y[1] (state B): only A --1--> B
    assign Y1 = y[0] & w;

    // Y3 is next-state for y[3] (state D): B/C/E/F --0--> D
    assign Y3 = (~w) & (y[1] | y[2] | y[4] | y[5]);

endmodule
"
  }
}

